n# optional (staged into ``bin/`` by install.py / tools/sync_native.py); when it\n# is absent the shim simply falls back to its pure-Python ``_compat`` code.\n[tool.hatch.build.targets.wheel.force-include]\n\"bin/kimix_native\" = \"kimix_native\"\n\n[tool.uv]\nlink-mode = \"symlink\"\n\n[tool.uv.workspace]\nmembers = [\n    \"kimi-cli\",\n]\n\n[tool.uv.sources]\nkimi-cli-x = { workspace = true }\n\n[tool.ruff]\ntarget-version = \"py315\"\nline-length = 100\n\n[tool.ruff.lint]\nselect = [\n    \"E\",   # pycodestyle errors\n    \"F\",   # Pyflakes\n    \"I\",   # isort\n    \"N\",   # pep8-naming\n    \"W\",   # pycodestyle warnings\n]\nignore = [\n    \"E501\",  # Line too long (handled by formatter)\n]\n\n[project.scripts]\nkimix = \"kimix.cli:cli\"\n\n[tool.mypy]\n# Strict mode switch\nstrict = true\n\n# Interpreter the type checker targets (mirrors requires-python).\npython_version = \"3.15\"\n\n# Or manually enable individual strict checks (when strict = false)\nwarn_return_any = true\nwarn_unused_configs = true\nwarn_redundant_casts = true\nwarn_unused_ignores = true\nwarn_no_return = true\nwarn_unreachable = true\n\n# Disallow implicit optional (None must be explicitly declared)\nno_implicit_optional = true\n\n# Check untyped definitions\ndisallow_untyped_defs = true\ndisallow_incomplete_defs = true\ndisallow_untyped_calls = true\n\n# Check Any types\ndisallow_any_generics = true\n\n# Other useful options\nshow_error_codes = true        # Show error codes for easy # type: ignore[xxx]\nignore_missing_imports = true  # Skip when third-party libraries lack type stubs\nexclude = [\"tests/\", \"scripts/\"]\n\n[tool.pytest.ini_options]\n  asyncio_mode = \"auto\"\n  testpaths = [\"tests\"]\n  pythonpath = [\".\"]\nmarkers = [\n    \"slow: marks tests as slow (deselect with '-m \\\"not slow\\\"')\",\n]\n\n[dependency-groups]\ndev = [\n    \"inline-snapshot>=0.33.0\",\n    \"pytest>=9.0.2\",\n    \"pytest-asyncio>=1.3.0\",\n    \"ruff>=0.15.10\",\n    \"mypy>=1.5.0\",\n    \"respx>=0.22.0\",\n    \"xlwt>=1.3.0\",\n    # Editor formatter stack for the VS Code ms-python.autopep8 extension.\n    # Declared here so `uv sync` keeps it: the extension's own bundled copies only\n    # support Python <= 3.14 (its typing_extensions reads the removed\n    # `typing.no_type_check_decorator`), so .vscode/settings.json sets\n    # \"autopep8.importStrategy\": \"fromEnvironment\" and these must exist in the venv.\n    # pygls must stay on the 1.x line: 2.x dropped `pygls.server.LanguageServer`,\n    # which the extension's bundled lsp_server.py still imports.\n    \"autopep8>=2.3.2\",\n    \"pygls>=1.3,<2\",\n    \"cattrs>=25.1.0\",\n    \"typing_extensions>=4.16.0\",\n]\n"
